{
  "id": "openmm-trading",
  "configSchema": {
    "type": "object",
    "properties": {
      "exchange": { "type": "string", "enum": ["mexc", "gateio", "kraken", "bitget"] },
      "apiKey": { "type": "string" },
      "secretKey": { "type": "string" },
      "passphrase": { "type": "string" }
    }
  },
  "uiHints": {
    "apiKey": { "label": "Exchange API Key", "sensitive": true },
    "secretKey": { "label": "Exchange Secret Key", "sensitive": true },
    "passphrase": { "label": "Passphrase (Bitget only)", "sensitive": true }
  }
}

{
  "name": "@qbtlabs/openmm-trading",
  "version": "0.1.0",
  "description": "Exchange setup, order management, and grid trading strategies for OpenMM",
  "keywords": ["openmm", "trading", "grid", "market-making", "agent-skills"],
  "files": ["skills", "references", "agents", "openclaw.plugin.json", "CLAUDE.md", "README.md"],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/QBT-Labs/OpenMM-ai.git",
    "directory": "packages/plugins/openmm-trading"
  },
  "dependencies": {
    "@3rd-eye-labs/openmm": "latest"
  }
}
